import math

def is_power_of_two(n):
    """Checks if n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

# Search for n=4, x from 5 up to 50
solutions = []
x_start = 5
x_end = 50

for x in range(x_start, x_end + 1):
    # The equation is x^4 + x = 2^k + 2, which means x^4 + x - 2 = 2^k
    N = x**4 + x - 2

    if is_power_of_two(N):
        # If N is a power of 2, k = log2(N)
        k = N.bit_length() - 1
        solutions.append((x, 4, k))

print("Solutions found for n=4 (x <= 50):")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found.")

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    return n > 0 and (n & (n - 1) == 0)

solutions_n3 = []
